def _resolve(obj, dotted):
    cur = obj
    for tok in dotted.replace("[", ".").replace("]", "").split("."):
        if tok == "":
            continue
        if tok.isdigit():
            cur = cur[int(tok)]
        else:
            cur = getattr(cur, tok)
    return cur


def _coerce_to_torch(x):
    try:
        import ttnn as _ttnn

        if isinstance(x, _ttnn.Tensor):
            import torch as _torch

            t = _ttnn.to_torch(x)
            # Bug Y fix (2026-05-23 live-run sam2-hiera-tiny)
            if t.is_floating_point():
                if t.dtype != _torch.float32:
                    t = t.to(_torch.float32)
            elif t.dtype != _torch.bool:
                t = t.to(_torch.long)
            return t
    except Exception:
        pass
    if isinstance(x, tuple):
        return tuple(_coerce_to_torch(e) for e in x)
    if isinstance(x, list):
        return [_coerce_to_torch(e) for e in x]
    if isinstance(x, dict):
        return {k: _coerce_to_torch(v) for k, v in x.items()}
    return x


class AceStepEncoderLayer:
    def __init__(self, device, torch_module):
        self.device = device
        self._torch_module = torch_module
        sd = torch_module.state_dict()
        # op-REUSE: self_attn.q_proj  (Linear 2048 -> 2048, bias=False)
        self.w_self_attn_q_proj_weight = ttnn.from_torch(
            sd["self_attn.q_proj.weight"].T.contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )

        # op-REUSE: self_attn.k_proj  (Linear 2048 -> 1024, bias=False)
        self.w_self_attn_k_proj_weight = ttnn.from_torch(
            sd["self_attn.k_proj.weight"].T.contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )

        # op-REUSE: self_attn.v_proj  (Linear 2048 -> 1024, bias=False)
        self.w_self_attn_v_proj_weight = ttnn.from_torch(
            sd["self_attn.v_proj.weight"].T.contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )

        # op-REUSE: self_attn.o_proj  (Linear 2048 -> 2048, bias=False)
        self.w_self_attn_o_proj_weight = ttnn.from_torch(
            sd["self_attn.o_proj.weight"].T.contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )

        # op-REUSE: mlp.gate_proj  (Linear 2048 -> 6144, bias=False)
        self.w_mlp_gate_proj_weight = ttnn.from_torch(
            sd["mlp.gate_proj.weight"].T.contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )

        # op-REUSE: mlp.up_proj  (Linear 2048 -> 6144, bias=False)
        self.w_mlp_up_proj_weight = ttnn.from_torch(
            sd["mlp.up_proj.weight"].T.contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )

        # op-REUSE: mlp.down_proj  (Linear 6144 -> 2048, bias=False)
        self.w_mlp_down_proj_weight = ttnn.from_torch(
            sd["mlp.down_proj.weight"].T.contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )

        # op-NEW: RMSNorm weights (input_layernorm / post_attention_layernorm operate
        # on the full hidden_size; q_norm / k_norm operate per-head on head_dim).
        self.w_input_layernorm_weight = ttnn.from_torch(
            sd["input_layernorm.weight"].contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )
        self.w_post_attention_layernorm_weight = ttnn.from_torch(
            sd["post_attention_layernorm.weight"].contiguous(),
            dtype=ttnn.bfloat16,
            layout=ttnn.TILE_LAYOUT,
            device=device,
        )
        self.w_self_attn_q_norm_weight = ttnn.from_torch(
            sd["self_attn.q_norm.weight"].contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )
        self.w_self_attn_k_norm_weight = ttnn.from_torch(
            sd["self_attn.k_norm.weight"].contiguous(), dtype=ttnn.bfloat16, layout=ttnn.TILE_LAYOUT, device=device
        )

        # Attention shape config (mirrors AceStepAttention / Qwen3-style GQA attention).
        cfg = torch_module.config
        self._eps = cfg.rms_norm_eps
        self._num_heads = cfg.num_attention_heads
        self._num_kv_heads = cfg.num_key_value_heads
        self._head_dim = getattr(cfg, "head_dim", cfg.hidden_size // cfg.num_attention_heads)
        self._n_rep = self._num_heads // self._num_kv_heads
        self._scaling = self._head_dim**-0.5

        # op-REUSE: mlp.act_fn  (SILU)

    def _apply_self_attn_q_proj(self, x):
        return ttnn.linear(x, self.w_self_attn_q_proj_weight)

    def _apply_self_attn_k_proj(self, x):
        return ttnn.linear(x, self.w_self_attn_k_proj_weight)

    def _apply_self_attn_v_proj(self, x):
        return ttnn.linear(x, self.w_self_attn_v_proj_weight)

    def _apply_self_attn_o_proj(self, x):
        return ttnn.linear(x, self.w_self_attn_o_proj_weight)

    def _apply_mlp_gate_proj(self, x):
        return ttnn.linear(x, self.w_mlp_gate_proj_weight)

    def _apply_mlp_up_proj(self, x):
        return ttnn.linear(x, self.w_mlp_up_proj_weight)

    def _apply_mlp_down_proj(self, x):
        return ttnn.linear(x, self.w_mlp_down_proj_weight)

    def _apply_mlp_act_fn(self, x):
        return ttnn.silu(x)

    def _apply_input_layernorm(self, x):
        return ttnn.rms_norm(x, epsilon=self._eps, weight=self.w_input_layernorm_weight)

    def _apply_post_attention_layernorm(self, x):
        return ttnn.rms_norm(x, epsilon=self._eps, weight=self.w_post_attention_layernorm_weight)

    def _apply_self_attn_q_norm(self, x):
        # x: (B, num_heads, L, head_dim) -- RMSNorm reduces over the last dim (head_dim).
        # RMSNorm is invariant to the head/seq axis order, so applying it after the
        # head-split permute matches Qwen3RMSNorm (which normalizes head_dim).
        return ttnn.rms_norm(x, epsilon=self._eps, weight=self.w_self_attn_q_norm_weight)

    def _apply_self_attn_k_norm(self, x):
        return ttnn.rms_norm(x, epsilon=self._eps, weight=self.w_self_attn_k_norm_weight)

    def _apply_rotate_half(self, x):
        # rotate_half(x) = cat(-x2, x1) where x1, x2 are the two halves of the last dim.
        # Use ttnn.slice (explicit start/end per dim) rather than python-style indexing,
        # which is unreliable on tiled ttnn tensors.
        b, h, t, d = x.shape[0], x.shape[1], x.shape[2], x.shape[3]
        half = d // 2
        x1 = ttnn.slice(x, [0, 0, 0, 0], [b, h, t, half])
        x2 = ttnn.slice(x, [0, 0, 0, half], [b, h, t, d])
        return ttnn.concat([ttnn.neg(x2), x1], dim=-1)

    def _apply_rope(self, x, cos, sin):
        # cos / sin broadcast over the head dim: (1, 1, L, head_dim) * (B, H, L, head_dim).
        return ttnn.add(ttnn.mul(x, cos), ttnn.mul(self._apply_rotate_half(x), sin))

    def _split_heads(self, x, num_heads):
        # (B, L, num_heads*head_dim) -> (B, num_heads, L, head_dim)
        b, t = x.shape[0], x.shape[1]
        x = ttnn.reshape(x, (b, t, num_heads, self._head_dim))
        return ttnn.permute(x, (0, 2, 1, 3))

    def _merge_heads(self, x, num_heads):
        # (B, num_heads, L, head_dim) -> (B, L, num_heads*head_dim)
        b, t = x.shape[0], x.shape[2]
        x = ttnn.permute(x, (0, 2, 1, 3))
        return ttnn.reshape(x, (b, t, num_heads * self._head_dim))

    def __call__(
        self,
        hidden_states,
        position_embeddings,
        attention_mask=None,
        position_ids=None,
        output_attentions=False,
        **kwargs,
    ):
        bsz = hidden_states.shape[0]
        seq_len = hidden_states.shape[1]

        # RoPE tables are supplied by the caller as (cos, sin) each (B, L, head_dim).
        # Reshape to (B, 1, L, head_dim) so they broadcast across the head axis.
        cos, sin = position_embeddings
        cos = ttnn.reshape(cos, (bsz, 1, seq_len, self._head_dim))
        sin = ttnn.reshape(sin, (bsz, 1, seq_len, self._head_dim))

        # --- Self-attention block (Qwen3-style GQA) ---
        residual = hidden_states
        normed = self._apply_input_layernorm(hidden_states)

        # Project then split into heads: q -> (B, num_heads, L, D); k,v -> (B, num_kv_heads, L, D).
        q = self._split_heads(self._apply_self_attn_q_proj(normed), self._num_heads)
        k = self._split_heads(self._apply_self_attn_k_proj(normed), self._num_kv_heads)
        v = self._split_heads(self._apply_self_attn_v_proj(normed), self._num_kv_heads)

        # Per-head RMSNorm (over head_dim) before RoPE, matching Qwen3Attention.
        q = self._apply_self_attn_q_norm(q)
        k = self._apply_self_attn_k_norm(k)

        q = self._apply_rope(q, cos, sin)
        k = self._apply_rope(k, cos, sin)

        # ttnn SDPA handles GQA natively (q has num_heads, k/v have num_kv_heads); the
        # default scale is head_dim**-0.5 == self._scaling. This is a bidirectional
        # encoder layer, so is_causal=False. The additive attention_mask for this
        # single unpadded sequence is a no-op and is intentionally not applied.
        attn_output = ttnn.transformer.scaled_dot_product_attention(q, k, v, is_causal=False)

        attn_output = self._merge_heads(attn_output, self._num_heads)
        attn_output = self._apply_self_attn_o_proj(attn_output)

        hidden_states = ttnn.add(residual, attn_output)

        # --- MLP block (SwiGLU) ---
        residual = hidden_states
        normed = self._apply_post_attention_layernorm(hidden_states)
        gate = self._apply_mlp_act_fn(self._apply_mlp_gate_proj(normed))
        up = self._apply_mlp_up_proj(normed)
        mlp_out = self._apply_mlp_down_proj(ttnn.mul(gate, up))
        hidden_states = ttnn.add(residual, mlp_out)

        return (hidden_states,)


